//! C-alignment regression tests (step H6: the page cache decides like C — cache limit, dirty pages written out in the
//! middle of a transaction, clean pages recycled; `PRAGMA cache_size` / `cache_spill` / `shrink_memory`). GENERATED by
//! target/perf-work/h6/gen_tests6.py: every expected value is what C SQLite 3.54.1 produces — size and FNV-1a hash of
//! the database file C writes for the statements, and the rows C returns. The file cases fail with the code before
//! step H6 unless noted (it never wrote a page before COMMIT in rollback-journal mode); nothing here depends on files
//! outside the repository.
use crate::Connection;

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h6-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn assert_file_is_what_c_writes(name: &str, stmts: &[&str], c_size: usize, c_hash: u64) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        // (a statement may fail, as it does in the C shell that produced the expected file:
        // the script goes on)
        let _ = conn.query(sql, &[]);
    }
    assert!(conn.try_close().is_ok());
    let bytes = std::fs::read(&db.0).unwrap();
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(fnv1a(&bytes), c_hash, "{name}: file content differs from C");
}

/// Runs the statements; `c_out` is what the C shell prints for them (rows as `a|b`, one per line; the lines of an
/// EXPLAIN QUERY PLAN are its `detail` column), `c_errors` the messages of the statements that fail, in order.
fn assert_rows_and_errors_are_what_c_returns(
    name: &str,
    stmts: &[&str],
    c_out: &str,
    c_errors: &[&str],
) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    let mut out = String::new();
    let mut errors: Vec<String> = Vec::new();
    for sql in stmts {
        let eqp = sql.starts_with("EXPLAIN QUERY PLAN");
        match conn.query(sql, &[]) {
            Ok(res) => {
                for row in &res.rows {
                    let cells: Vec<String> = row
                        .values
                        .iter()
                        .map(|v| match v {
                            sqliters_types::Value::Null => String::new(),
                            sqliters_types::Value::Integer(i) => i.to_string(),
                            sqliters_types::Value::Real(r) => format!("{r:?}"),
                            sqliters_types::Value::Text(s) => s.to_string(),
                            sqliters_types::Value::Blob(b) => {
                                String::from_utf8_lossy(&b[..]).into_owned()
                            }
                        })
                        .collect();
                    if eqp {
                        out.push_str(cells.last().map_or("", String::as_str));
                    } else {
                        out.push_str(&cells.join("|"));
                    }
                    out.push('\n');
                }
            }
            Err(e) => errors.push(e.message.clone()),
        }
    }
    assert!(conn.try_close().is_ok());
    assert_eq!(out, c_out, "{name}: rows");
    assert_eq!(errors, c_errors, "{name}: error messages");
}

/// A transaction dirties more pages than the default cache holds (483 pages of 4096 bytes): C writes the oldest dirty pages into the database file while the transaction runs. `DELETE FROM x` then frees them as free-list leaves, which are not written again, so the file keeps what was written early.
#[test]
fn pages_written_out_before_commit_keep_their_content_when_freed() {
    assert_file_is_what_c_writes(
        "pages_written_out_before_commit_keep_their_content_when_freed",
        &[
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<30000) INSERT INTO x SELECT x, printf('%0100d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        3338240,
        0x5197db254cf92700,
    );
}

/// `PRAGMA cache_size=10` with 1024-byte pages: nearly every new page pushes an older dirty page out; the freed pages keep the image they had at that moment.
#[test]
fn small_cache_1024_byte_pages_spill_and_free() {
    assert_file_is_what_c_writes(
        "small_cache_1024_byte_pages_spill_and_free",
        &[
            "PRAGMA page_size=1024;",
            "PRAGMA cache_size=10;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<5000) INSERT INTO x SELECT x, printf('%080d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        472064,
        0x4ac6cb81f23ade5d,
    );
}

/// Table and two index b-trees filled in one transaction with a 20-page cache (page splits, renumbered sibling pages, the dirty-list order after each `balance_nonroot`), then everything freed.
#[test]
fn spill_with_two_indexes_then_delete_all() {
    assert_file_is_what_c_writes(
        "spill_with_two_indexes_then_delete_all",
        &[
            "PRAGMA cache_size=20;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT, c INT);",
            "CREATE INDEX xb ON x(b);",
            "CREATE INDEX xc ON x(c);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<4000) INSERT INTO x(b, c) SELECT printf('%060d', (x*7919)%100003), x%97 FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        659456,
        0xe6710263795591ae,
    );
}

