/// `PRAGMA cache_size` inside a transaction: the limit changes at once (clean pages beyond it leave the cache), the following fetches spill by the new limit.
#[test]
fn cache_size_changed_inside_the_transaction() {
    assert_file_is_what_c_writes(
        "cache_size_changed_inside_the_transaction",
        &[
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<3000) INSERT INTO x SELECT x, printf('%0100d', x) FROM c;",
            "PRAGMA cache_size=8;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<3000) INSERT INTO x SELECT x + 100000, printf('%0100d', x) FROM c;",
            "PRAGMA cache_size=-400;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<3000) INSERT INTO x SELECT x + 200000, printf('%0100d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        1007616,
        0x04a8fa42b5edc7ec,
    );
}

/// `PRAGMA cache_spill=0`: nothing is written before COMMIT however small the cache is, so the freed pages were never written (the file has zeroes there). (The code before step H6 produced this file too.)
#[test]
fn cache_spill_off_keeps_every_dirty_page_in_memory() {
    assert_file_is_what_c_writes(
        "cache_spill_off_keeps_every_dirty_page_in_memory",
        &[
            "PRAGMA cache_size=10;",
            "PRAGMA cache_spill=0;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<4000) INSERT INTO x SELECT x, printf('%0100d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        454656,
        0x44cb763bc07c8faf,
    );
}

/// `PRAGMA cache_spill=200` with `cache_size=10`: the cache grows to 200 pages before the first dirty page is written out.
#[test]
fn cache_spill_size_delays_the_first_write() {
    assert_file_is_what_c_writes(
        "cache_spill_size_delays_the_first_write",
        &[
            "PRAGMA cache_size=10;",
            "PRAGMA cache_spill=200;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<20000) INSERT INTO x SELECT x, printf('%0100d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        2232320,
        0xcfb0824c85ee6e42,
    );
}

/// WAL mode: pages written out early become uncommitted frames; the page freed later is not written again, so the checkpoint copies the early frame into the database file. (The code before step H6 produced this file too.)
#[test]
fn wal_mode_spilled_frames_then_delete_all() {
    assert_file_is_what_c_writes(
        "wal_mode_spilled_frames_then_delete_all",
        &[
            "PRAGMA journal_mode=wal;",
            "PRAGMA cache_size=15;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<6000) INSERT INTO x SELECT x, printf('%0100d', x) FROM c;",
            "DELETE FROM x;",
            "COMMIT;",
        ],
        675840,
        0xc37ebaab55d1c33b,
    );
}

/// ROLLBACK of a transaction whose pages were partly written into the database file: the journal brings every page back and the file is cut to its original size. (The code before step H6 produced this file too.)
#[test]
fn rollback_after_spill_restores_the_file() {
    assert_file_is_what_c_writes(
        "rollback_after_spill_restores_the_file",
        &[
            "PRAGMA cache_size=10;",
            "CREATE TABLE x(a INTEGER PRIMARY KEY, b TEXT);",
            "INSERT INTO x VALUES(1, 'kept');",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<5000) INSERT INTO x SELECT x + 10, printf('%0100d', x) FROM c;",
            "ROLLBACK;",
            "INSERT INTO x VALUES(2, 'after');",
        ],
        8192,
        0xcbc99183a3f4dba5,
    );
}

/// `PRAGMA cache_size=0` in WAL mode: page 1 leaves the cache whenever its last reference is released, so every transaction reads it again (`readDbPage`) and the change counter stamped by the next commit that writes page 1 is one more than the value read — with a page 1 that stays cached the counter would stay at 2.
#[test]
fn page_one_read_again_brings_the_change_counter_of_the_file() {
    assert_file_is_what_c_writes(
        "page_one_read_again_brings_the_change_counter_of_the_file",
        &[
            "PRAGMA journal_mode=wal;",
            "PRAGMA cache_size=0;",
            "CREATE TABLE t(a);",
            "CREATE TABLE u(a);",
            "CREATE TABLE v(a);",
        ],
        16384,
        0x850cb4f46d81d079,
    );
}

/// `PRAGMA cache_spill`: the value in force (never below the cache size), 0 when switched off; `PRAGMA shrink_memory` returns nothing.
#[test]
fn pragma_cache_spill_reports_and_sets_like_c() {
    assert_rows_and_errors_are_what_c_returns(
        "pragma_cache_spill_reports_and_sets_like_c",
        &[
            "PRAGMA cache_spill;",
            "PRAGMA cache_size=50;",
            "PRAGMA cache_spill;",
            "PRAGMA cache_spill=300;",
            "PRAGMA cache_spill;",
            "PRAGMA cache_spill=off;",
            "PRAGMA cache_spill;",
            "PRAGMA cache_spill=on;",
            "PRAGMA cache_spill;",
            "PRAGMA cache_spill=-100;",
            "PRAGMA cache_spill;",
            "PRAGMA cache_spill=0;",
            "PRAGMA cache_spill;",
            "PRAGMA shrink_memory;",
            "PRAGMA cache_size;",
        ],
        "483\n50\n300\n0\n300\n50\n0\n50\n",
        &[
        ],
    );
}
